import { BFastDecoder } from "./index";

// Embedded WebAssembly module compiled from Rust (lz4_flex + B-FAST WASM core)
export const WASM_LZ4_BASE64 = "";

export type WasmDecodeResult =
    | { success: true; value: any }
    | { success: false; reason: "extended_types" | "error"; decompressed?: Uint8Array };

let wasmInstance: WebAssembly.Instance | null = null;
let allocFn: ((size: number) => number) | null = null;
let deallocFn: ((ptr: number, size: number) => void) | null = null;
let decompressFn: ((srcPtr: number, srcLen: number, dstPtr: number, dstLen: number) => number) | null = null;
let decompressParallelFn: ((srcPtr: number, srcLen: number, dstPtr: number, dstLen: number) => number) | null = null;
let decodeToJsonFn: ((srcPtr: number, srcLen: number) => number) | null = null;
let getResultPtrFn: (() => number) | null = null;
let getResultLenFn: (() => number) | null = null;
let getDecompressedPtrFn: (() => number) | null = null;
let getDecompressedLenFn: (() => number) | null = null;

// BFastTable WASM bindings
let tableCreateFn: ((srcPtr: number, srcLen: number) => number) | null = null;
let tableDestroyFn: ((tablePtr: number) => void) | null = null;
let tableRowCountFn: ((tablePtr: number) => number) | null = null;
let tableColumnCountFn: ((tablePtr: number) => number) | null = null;
let tableGetColumnNamePtrFn: ((tablePtr: number, colIdx: number) => number) | null = null;
let tableGetColumnNameLenFn: ((tablePtr: number, colIdx: number) => number) | null = null;
let tableGetColumnTypeFn: ((tablePtr: number, colIdx: number) => number) | null = null;
let tableGetColumnDataPtrFn: ((tablePtr: number, colIdx: number) => number) | null = null;
let tableGetColumnDataLenFn: ((tablePtr: number, colIdx: number) => number) | null = null;
let tableGetColumnOffsetsPtrFn: ((tablePtr: number, colIdx: number) => number) | null = null;
let tableGetColumnOffsetsLenFn: ((tablePtr: number, colIdx: number) => number) | null = null;
let tableAggregateF64Fn: ((tablePtr: number, colIdx: number, aggType: number) => number) | null = null;
let tableAggregateI64Fn: ((tablePtr: number, colIdx: number, aggType: number) => bigint) | null = null;
let tableFilterF64Fn: ((tablePtr: number, colIdx: number, op: number, target: number) => number) | null = null;
let tableGetFilterIndicesPtrFn: (() => number) | null = null;

let wasmMemory: WebAssembly.Memory | null = null;
const UTF8_DECODER = new TextDecoder();

export interface WasmTableBindings {
    alloc: (size: number) => number;
    dealloc: (ptr: number, size: number) => void;
    tableCreate: (srcPtr: number, srcLen: number) => number;
    tableDestroy: (tablePtr: number) => void;
    tableRowCount: (tablePtr: number) => number;
    tableColumnCount: (tablePtr: number) => number;
    tableGetColumnNamePtr: (tablePtr: number, colIdx: number) => number;
    tableGetColumnNameLen: (tablePtr: number, colIdx: number) => number;
    tableGetColumnType: (tablePtr: number, colIdx: number) => number;
    tableGetColumnDataPtr: (tablePtr: number, colIdx: number) => number;
    tableGetColumnDataLen: (tablePtr: number, colIdx: number) => number;
    tableGetColumnOffsetsPtr: (tablePtr: number, colIdx: number) => number;
    tableGetColumnOffsetsLen: (tablePtr: number, colIdx: number) => number;
    tableAggregateF64: (tablePtr: number, colIdx: number, aggType: number) => number;
    tableAggregateI64: (tablePtr: number, colIdx: number, aggType: number) => bigint;
    tableFilterF64: (tablePtr: number, colIdx: number, op: number, target: number) => number;
    tableGetFilterIndicesPtr: () => number;
    getMemory: () => WebAssembly.Memory;
}

export function getWasmTableBindings(): WasmTableBindings | null {
    if (!wasmInstance || !tableCreateFn || !wasmMemory) {
        return null;
    }
    return {
        alloc: allocFn!,
        dealloc: deallocFn!,
        tableCreate: tableCreateFn,
        tableDestroy: tableDestroyFn!,
        tableRowCount: tableRowCountFn!,
        tableColumnCount: tableColumnCountFn!,
        tableGetColumnNamePtr: tableGetColumnNamePtrFn!,
        tableGetColumnNameLen: tableGetColumnNameLenFn!,
        tableGetColumnType: tableGetColumnTypeFn!,
        tableGetColumnDataPtr: tableGetColumnDataPtrFn!,
        tableGetColumnDataLen: tableGetColumnDataLenFn!,
        tableGetColumnOffsetsPtr: tableGetColumnOffsetsPtrFn!,
        tableGetColumnOffsetsLen: tableGetColumnOffsetsLenFn!,
        tableAggregateF64: tableAggregateF64Fn!,
        tableAggregateI64: tableAggregateI64Fn!,
        tableFilterF64: tableFilterF64Fn!,
        tableGetFilterIndicesPtr: tableGetFilterIndicesPtrFn!,
        getMemory: () => wasmMemory!,
    };
}

export function base64ToUint8Array(base64: string): Uint8Array {
    if (typeof Buffer !== "undefined") {
        const buf = Buffer.from(base64, "base64");
        return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
    }
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
}

function setupInstance(instance: WebAssembly.Instance): void {
    wasmInstance = instance;
    allocFn = instance.exports.alloc as (size: number) => number;
    deallocFn = instance.exports.dealloc as (ptr: number, size: number) => void;
    decompressFn = instance.exports.decompress as (
        srcPtr: number,
        srcLen: number,
        dstPtr: number,
        dstLen: number
    ) => number;
    decompressParallelFn = (instance.exports.decompress_parallel as any) || null;
    decodeToJsonFn = (instance.exports.decode_to_json as any) || null;
    getResultPtrFn = (instance.exports.get_result_ptr as any) || null;
    getResultLenFn = (instance.exports.get_result_len as any) || null;
    getDecompressedPtrFn = (instance.exports.get_decompressed_ptr as any) || null;
    getDecompressedLenFn = (instance.exports.get_decompressed_len as any) || null;

    // Table bindings
    tableCreateFn = (instance.exports.table_create as any) || null;
    tableDestroyFn = (instance.exports.table_destroy as any) || null;
    tableRowCountFn = (instance.exports.table_row_count as any) || null;
    tableColumnCountFn = (instance.exports.table_column_count as any) || null;
    tableGetColumnNamePtrFn = (instance.exports.table_get_column_name_ptr as any) || null;
    tableGetColumnNameLenFn = (instance.exports.table_get_column_name_len as any) || null;
    tableGetColumnTypeFn = (instance.exports.table_get_column_type as any) || null;
    tableGetColumnDataPtrFn = (instance.exports.table_get_column_data_ptr as any) || null;
    tableGetColumnDataLenFn = (instance.exports.table_get_column_data_len as any) || null;
    tableGetColumnOffsetsPtrFn = (instance.exports.table_get_column_offsets_ptr as any) || null;
    tableGetColumnOffsetsLenFn = (instance.exports.table_get_column_offsets_len as any) || null;
    tableAggregateF64Fn = (instance.exports.table_aggregate_f64 as any) || null;
    tableAggregateI64Fn = (instance.exports.table_aggregate_i64 as any) || null;
    tableFilterF64Fn = (instance.exports.table_filter_f64 as any) || null;
    tableGetFilterIndicesPtrFn = (instance.exports.table_get_filter_indices_ptr as any) || null;

    wasmMemory = instance.exports.memory as WebAssembly.Memory;

    // Register with BFastDecoder
    BFastDecoder.setDecompressor(wasmDecompress);
    BFastDecoder.setWasmParallelDecompressor(wasmDecompressParallel);
    BFastDecoder.setWasmDecoder(wasmDecode);
}

/**
 * Decompress LZ4 payload using native WebAssembly.
 */
export function wasmDecompress(compressed: Uint8Array, uncompressedSize: number): Uint8Array {
    if (!allocFn || !deallocFn || !decompressFn || !wasmMemory) {
        throw new Error("WebAssembly LZ4 decompressor is not initialized");
    }

    const srcPtr = allocFn(compressed.length);
    const dstPtr = allocFn(uncompressedSize);

    try {
        new Uint8Array(wasmMemory.buffer, srcPtr, compressed.length).set(compressed);
        const len = decompressFn(srcPtr, compressed.length, dstPtr, uncompressedSize);
        if (len < 0) {
            throw new Error("WebAssembly LZ4 decompression returned error code " + len);
        }
        return new Uint8Array(wasmMemory.buffer, dstPtr, len).slice(0);
    } finally {
        deallocFn(srcPtr, compressed.length);
        deallocFn(dstPtr, uncompressedSize);
    }
}

/**
 * Decompress parallel-chunked LZ4 payload using native WebAssembly.
 */
export function wasmDecompressParallel(src: Uint8Array, uncompressedSize: number): Uint8Array | null {
    if (!allocFn || !deallocFn || !decompressParallelFn || !wasmMemory) {
        return null;
    }

    const srcPtr = allocFn(src.length);
    const dstPtr = allocFn(uncompressedSize);

    try {
        new Uint8Array(wasmMemory.buffer, srcPtr, src.length).set(src);
        const len = decompressParallelFn(srcPtr, src.length, dstPtr, uncompressedSize);
        if (len < 0) {
            return null;
        }
        return new Uint8Array(wasmMemory.buffer, dstPtr, len).slice(0);
    } catch {
        return null;
    } finally {
        deallocFn(srcPtr, src.length);
        deallocFn(dstPtr, uncompressedSize);
    }
}

/**
 * Decode B-FAST binary payload directly in WebAssembly to JavaScript objects.
 */
export function wasmDecode(data: Uint8Array): WasmDecodeResult {
    if (!allocFn || !deallocFn || !decodeToJsonFn || !getResultPtrFn || !getResultLenFn || !wasmMemory) {
        return { success: false, reason: "error" };
    }

    const srcPtr = allocFn(data.length);
    try {
        new Uint8Array(wasmMemory.buffer, srcPtr, data.length).set(data);
        const status = decodeToJsonFn(srcPtr, data.length);
        if (status >= 0) {
            const resPtr = getResultPtrFn();
            const resLen = getResultLenFn();
            const jsonBytes = new Uint8Array(wasmMemory.buffer, resPtr, resLen);
            const jsonText = UTF8_DECODER.decode(jsonBytes);
            const parsed = JSON.parse(jsonText);
            return { success: true, value: parsed };
        } else if (status === -2) {
            let decompressed: Uint8Array | undefined;
            if (getDecompressedPtrFn && getDecompressedLenFn) {
                const decLen = getDecompressedLenFn();
                if (decLen > 0) {
                    const decPtr = getDecompressedPtrFn();
                    decompressed = new Uint8Array(wasmMemory.buffer, decPtr, decLen).slice(0);
                }
            }
            return { success: false, reason: "extended_types", decompressed };
        }
        return { success: false, reason: "error" };
    } catch {
        return { success: false, reason: "error" };
    } finally {
        deallocFn(srcPtr, data.length);
    }
}

/**
 * Check if WebAssembly acceleration is currently active.
 */
export function isWasmEnabled(): boolean {
    return wasmInstance !== null && BFastDecoder.getDecompressor() === wasmDecompress;
}

/**
 * Synchronously initialize WebAssembly acceleration.
 */
export function initWasmLz4Sync(wasmBinary?: ArrayBuffer | Uint8Array): boolean {
    if (isWasmEnabled()) return true;

    try {
        const bytes = wasmBinary ? (wasmBinary instanceof Uint8Array ? wasmBinary : new Uint8Array(wasmBinary)) : base64ToUint8Array(WASM_LZ4_BASE64);
        const module = new WebAssembly.Module(bytes as BufferSource);
        const instance = new WebAssembly.Instance(module, {});
        setupInstance(instance);
        return true;
    } catch (e) {
        console.warn("Failed to initialize WebAssembly synchronously:", e);
        return false;
    }
}

/**
 * Asynchronously initialize WebAssembly acceleration.
 */
export async function initWasmLz4(wasmBinary?: ArrayBuffer | Uint8Array): Promise<boolean> {
    if (isWasmEnabled()) return true;

    try {
        const bytes = wasmBinary ? (wasmBinary instanceof Uint8Array ? wasmBinary : new Uint8Array(wasmBinary)) : base64ToUint8Array(WASM_LZ4_BASE64);
        const compiled = await WebAssembly.instantiate(bytes as BufferSource, {});
        const instance = "instance" in compiled ? (compiled as WebAssembly.WebAssemblyInstantiatedSource).instance : (compiled as WebAssembly.Instance);
        setupInstance(instance);
        return true;
    } catch (e) {
        console.warn("Failed to initialize WebAssembly asynchronously:", e);
        return false;
    }
}
